def finding(title,assessment,refs,controls,next_action):F.append({'id':f'RDR-F{len(F)+1:02d}','title':title,'assessment':assessment,'source_evidence':[ev(*r) for r in refs],'independent_controls':controls,'next_action':next_action,'limits':'Source review and explicitly independent finite controls only; no Rust build/test execution.'})
